def parse_cost_dollars(raw: Optional[dict]) -> Optional['CostDollars']:
    if raw is None:
        return None
    total = raw.get("total")
    if total is None:
        return None
    search_part = raw.get("search")
    contents_part = raw.get("contents")
    return CostDollars(
        total=total,
        search=search_part if search_part else None,
        contents=contents_part if contents_part else None
