class StreamAnswerResponse:
    def __init__(self, raw_response: requests.Response):
        self.raw_response = raw_response
        self._ensure_ok_status()

    def _ensure_ok_status(self):
        self.raw_response.raise_for_status()

    def __iter__(self) -> Iterator[StreamChunk]:
        for line in self.raw_response.iter_lines():
            if not line:
                continue
            try:
                decoded_line = line.decode("utf-8")
                if decoded_line.startswith("data: "):
                    decoded_line = decoded_line[6:]
                chunk = json.loads(decoded_line)
                content = None
                citations = None
                if "choices" in chunk and len(chunk["choices"]) > 0:
                    delta = chunk["choices"][0].get("delta", {})
                    content = delta.get("content")
                    raw_citations = delta.get("citations")
                    if raw_citations:
                        citations = []
                        for s in raw_citations:
                            snake_s = to_snake_case(s)
                            citations.append(AnswerResult(**snake_s))
                    else:
                        citations = None
                stream_chunk = StreamChunk(content=content, citations=citations)
                yield stream_chunk
            except (json.JSONDecodeError, KeyError, UnicodeDecodeError):
                continue

    def close(self) -> None:
        self.raw_response.close()

