def nest_fields(original_dict: Dict, fields_to_nest: List[str], new_key: str):
    nested_dict = {}
    for field_name in fields_to_nest:
        if field_name in original_dict:
            nested_dict[field_name] = original_dict.pop(field_name)
    if nested_dict:
        original_dict[new_key] = nested_dict
    return original_dict

class ExaJSONEncoder(json.JSONEncoder):
    def default(self, obj):
        if isinstance(obj, BaseModel):
