    def request(self, endpoint: str, data: Optional[Dict] = None, method: str = "POST"):
        if isinstance(data, str):
            json_data = data
        else:
            json_data = json.dumps(data, cls=ExaJSONEncoder) if data else None
        needs_streaming = False
        if data and isinstance(data, dict) and data.get("stream"):
            needs_streaming = True
        request_headers = {**self.headers}
        if method == "GET":
            res = requests.get(
                self.base_url + endpoint,
                params=data,
                headers=request_headers
            )
        elif method == "POST":
            if needs_streaming:
                res = requests.post(
                    self.base_url + endpoint,
                    data=json_data,
                    headers=request_headers,
                    stream=True
                )
                return res
            else:
                res = requests.post(
                    self.base_url + endpoint,
                    data=json_data,
                    headers=request_headers
                )
        elif method == "PATCH":
            res = requests.patch(
                self.base_url + endpoint,
                data=json_data,
                headers=request_headers
            )
        elif method == "DELETE":
            res = requests.delete(self.base_url + endpoint, headers=request_headers)
        else:
            raise ValueError(f"Unsupported HTTP method: {method}")
        res.raise_for_status()
        return res.json()

    def search(
        self,
        query: str,
        num_results: Optional[int] = None,
        include_domains: Optional[List[str]] = None,
        exclude_domains: Optional[List[str]] = None,
        start_crawl_date: Optional[str] = None,
        end_crawl_date: Optional[str] = None,
        start_published_date: Optional[str] = None,
        end_published_date: Optional[str] = None,
        use_autoprompt: Optional[bool] = None,
        type: Optional[str] = None,
        category: Optional[str] = None,
        livecrawl: Optional[LIVECRAWL_OPTIONS] = None,
        max_livecrawl_depth: Optional[int] = None,
        livecrawl_timeout: Optional[int] = None,
        include_text: Optional[List[str]] = None,
        exclude_text: Optional[List[str]] = None,
    ) -> SearchResponse[Result]:
        options = {k: v for k, v in locals().items() if k != "self" and v is not None}
        options = to_camel_case(options)
        data = self.request("/search", options)
        cost_dollars = parse_cost_dollars(data.get("costDollars"))
        results = []
        for result in data.get("results", []):
            snake_result = to_snake_case(result)
            results.append(Result(**snake_result))
        return SearchResponse(
            results=results,
            autoprompt_string=data.get("autopromptString"),
            resolved_search_type=data.get("resolvedSearchType"),
            auto_date=data.get("autoDate"),
            context=data.get("context"),
            statuses=[ContentStatus(**s) for s in data.get("statuses", [])],
            cost_dollars=cost_dollars
        )

    def search_and_contents(
        self,
        query: str,
        text: Optional[Union[bool, TextContentsOptions]] = None,
        highlights: Optional[Union[bool, HighlightsContentsOptions]] = None,
        summary: Optional[Union[bool, SummaryContentsOptions]] = None,
        **kwargs
