        options = {"query": query}
        options.update(kwargs)
        if text is None and highlights is None and summary is None:
            text = True
        merged_options = {}
        if text is not None:
            if isinstance(text, bool) and text:
                merged_options["text"] = {}
            elif isinstance(text, dict):
                merged_options["text"] = text
        if highlights is not None:
            if isinstance(highlights, bool) and highlights:
                merged_options["highlights"] = {}
            elif isinstance(highlights, dict):
                merged_options["highlights"] = highlights
        if summary is not None:
            if isinstance(summary, bool) and summary:
                merged_options["summary"] = {}
            elif isinstance(summary, dict):
                summary_opts = summary.copy()
                if "schema" in summary_opts:
                    summary_opts["schema"] = _convert_schema_input(summary_opts["schema"])
                merged_options["summary"] = summary_opts
        options["contents"] = merged_options
        options = to_camel_case(options, skip_keys=["schema"])
        data = self.request("/search", options)
        cost_dollars = parse_cost_dollars(data.get("costDollars"))
        results = []
        for result in data.get("results", []):
