            cost_dollars=cost_dollars
        )

    def wrap(
        self,
        client: OpenAI,
        model: str = "gpt-4",
        num_results: int = 10,
        max_len: int = 3000,
        use_autoprompt: bool = True,
        **kwargs
    ):
        from .utils import maybe_get_query, add_message_to_messages, format_exa_result, ExaOpenAICompletion
        func = client.chat.completions.create
        def wrapped_create(*args, **inner_kwargs):
            messages = inner_kwargs.get("messages") or (args[0] if len(args) > 0 else [])
            exa_kwargs = {
                "num_results": num_results,
                "use_autoprompt": use_autoprompt,
            }
            exa_kwargs.update(kwargs)
            create_kwargs = {"model": model}
            create_kwargs.update({k: v for k, v in inner_kwargs.items() if k != "messages"})
            tools = [
                {
                    "type": "function",
                    "function": {
                        "name": "exa_search",
                        "description": "Search for web pages",
                        "parameters": {
                            "type": "object",
                            "properties": {
                                "query": {
                                    "type": "string",
                                    "description": "The search query"
                                }
                            },
                            "required": ["query"]
                        }
                    }
                }
            ]
            create_kwargs["tools"] = tools
            create_kwargs["tool_choice"] = "auto"
            create_fn = func
            completion = create_fn(messages=messages, **create_kwargs)
            query = maybe_get_query(completion)
            if query:
                exa_result = self.search_and_contents(query, text=True, **exa_kwargs)
                exa_str = format_exa_result(exa_result, max_len=max_len)
                new_messages = add_message_to_messages(completion, messages, exa_str)
                completion = create_fn(messages=new_messages, **create_kwargs)
            exa_completion = ExaOpenAICompletion.from_completion(completion)
            return exa_completion
        return wrapped_create

    def answer(
        self,
        query: str,
        output_schema: Optional[JSONSchemaInput] = None,
        **kwargs
    ) -> AnswerResponse:
        options = {"query": query}
        options.update(kwargs)
        if output_schema is not None:
            options["output_schema"] = _convert_schema_input(output_schema)
        options = to_camel_case(options, skip_keys=["output_schema"])
