        needs_streaming = False
        if data and isinstance(data, dict) and data.get("stream"):
            needs_streaming = True
        request_headers = {**self.headers}
        if method == "GET":
            res = await self.client.get(
                self.base_url + endpoint,
                params=data,
                headers=request_headers
            )
        elif method == "POST":
            if needs_streaming:
                request = httpx.Request("POST", self.base_url + endpoint, data=json_data, headers=request_headers)
                res = await self.client.send(request, stream=True)
                return res
            else:
                res = await self.client.post(
                    self.base_url + endpoint,
                    data=json_data,
                    headers=request_headers
                )
        elif method == "PATCH":
            res = await self.client.patch(
                self.base_url + endpoint,
                data=json_data,
                headers=request_headers
            )
        elif method == "DELETE":
            res = await self.client.delete(self.base_url + endpoint, headers=request_headers)
        else:
            raise ValueError(f"Unsupported HTTP method: {method}")
        res.raise_for_status()
        return res.json()

