import os
import json
import sys
from typing import Any, Optional, Dict
from pydantic import BaseModel
from pydantic.json_schema import GenerateJsonSchema
from openai.types.chat import ChatCompletion

def maybe_get_query(completion) -> Optional[str]:
    try:
        if hasattr(completion, "choices") and len(completion.choices) > 0:
            message = completion.choices[0].message
            if hasattr(message, "tool_calls") and message.tool_calls and len(message.tool_calls) > 0:
                tool_call = message.tool_calls[0]
                if hasattr(tool_call, "function") and hasattr(tool_call.function, "arguments"):
                    args = json.loads(tool_call.function.arguments)
                    return args.get("query")
    except (json.JSONDecodeError, KeyError, AttributeError, IndexError):
        pass
    return None

def add_message_to_messages(completion, messages, exa_result) -> list[dict]:
    assistant_message = completion.choices[0].message
    tool_calls = assistant_message.tool_calls if hasattr(assistant_message, "tool_calls") else []
    tool_call_id = tool_calls[0].id if tool_calls and len(tool_calls) > 0 else "default_id"
    messages = [
        *messages,
        {
            "role": "assistant",
            "content": assistant_message.content,
            "tool_calls": [{"id": tc.id, "type": tc.type, "function": {"name": tc.function.name, "arguments": tc.function.arguments}} for tc in tool_calls] if tool_calls else None
        },
        {
            "role": "tool",
            "tool_call_id": tool_call_id,
            "content": exa_result
        }
    ]
    return messages

def format_exa_result(exa_result, max_len: int = -1):
    lines = []
    for idx, result in enumerate(exa_result.results, 1):
        lines.append(f"{idx}. {result.title}")
        lines.append(f"URL: {result.url}")
        if hasattr(result, "text") and result.text:
            text = result.text if max_len < 0 else result.text[:max_len]
            lines.append(f"Text: {text}")
        lines.append("")
    return "\n".join(lines)

class ExaOpenAICompletion(ChatCompletion):
    @classmethod
    def from_completion(cls, completion: ChatCompletion):
        return cls(**completion.model_dump())

JSONSchemaInput = Any

class InlineJsonSchemaGenerator(GenerateJsonSchema):
    def generate(self, schema, mode="validation"):
        result = super().generate(schema, mode)
        if "$defs" in result:
            definitions = result["$defs"]
            inlined_result = self._inline_refs(result, definitions)
            if "$defs" in inlined_result:
                del inlined_result["$defs"]
            return inlined_result
        return result

    def _inline_refs(self, obj, definitions):
        if isinstance(obj, dict):
            if "$ref" in obj:
                ref_path = obj["$ref"]
                if ref_path.startswith("#/$defs/"):
                    def_name = ref_path[8:]
                    if def_name in definitions:
                        return self._inline_refs(definitions[def_name], definitions)
                return obj
            return {k: self._inline_refs(v, definitions) for k, v in obj.items()}
        elif isinstance(obj, list):
            return [self._inline_refs(item, definitions) for item in obj]
        else:
            return obj

def _convert_schema_input(schema_input: JSONSchemaInput) -> dict[str, Any]:
    if isinstance(schema_input, type) and issubclass(schema_input, BaseModel):
        return schema_input.model_json_schema(mode="serialization", schema_generator=InlineJsonSchemaGenerator)
    elif isinstance(schema_input, dict):
        return schema_input
    else:
        raise ValueError("schema_input must be a Pydantic model class or a dict")

def _get_package_version() -> str:
    try:
        import tomllib
    except ImportError:
        import tomli as tomllib
    current_dir = os.path.dirname(os.path.abspath(__file__))
    project_root = os.path.dirname(current_dir)
    pyproject_path = os.path.join(project_root, "pyproject.toml")
    try:
        with open(pyproject_path, "rb") as f:
            data = tomllib.load(f)
            return data.get("project", {}).get("version", "unknown")
    except FileNotFoundError:
        return "unknown"
    except Exception:
        return "unknown"
