        )
        camel_data = to_camel_case(request_data.model_dump(by_alias=True, exclude_none=True), skip_keys=["outputSchema"])
        response = await self.http_client.async_request("/research", camel_data, method="POST")
        research = ResearchDto.model_validate(response)
        if wait and research.status in ["pending", "running"]:
            research = await self.wait_for_completion(research.research_id)
        return research

    async def get(self, research_id: str, include_events: bool = False) -> ResearchDto:
        params = {"includeEvents": "true" if include_events else "false"}
        response = await self.http_client.async_request(f"/research/{research_id}", params, method="GET")
        return ResearchDto.model_validate(response)

    async def list(self, cursor: Optional[str] = None, limit: int = 10) -> ListResearchResponseDto:
        params = {"limit": limit}
        if cursor:
            params["cursor"] = cursor
        response = await self.http_client.async_request("/research", params, method="GET")
        return ListResearchResponseDto.model_validate(response)

    async def list_all(self, limit: int = 100) -> List[ResearchDto]:
        all_items = []
        cursor = None
        while True:
            response = await self.list(cursor=cursor, limit=limit)
            all_items.extend(response.data)
            if not response.has_more or not response.next_cursor:
                break
            cursor = response.next_cursor
        return all_items

    async def cancel(self, research_id: str) -> ResearchDto:
        response = await self.http_client.async_request(f"/research/{research_id}/cancel", method="POST")
        return ResearchDto.model_validate(response)

    async def wait_for_completion(self, research_id: str, poll_interval: float = 2.0, timeout: Optional[float] = None) -> ResearchDto:
        start_time = time.time()
        consecutive_failures = 0
        max_consecutive_failures = 3
        while True:
            if timeout and (time.time() - start_time) > timeout:
                raise TimeoutError(f"Research {research_id} did not complete within {timeout} seconds")
            try:
                research = await self.get(research_id)
                consecutive_failures = 0
                if research.status in ["completed", "failed", "canceled"]:
                    return research
                await asyncio.sleep(poll_interval)
            except Exception as e:
                consecutive_failures += 1
                if consecutive_failures >= max_consecutive_failures:
                    raise Exception(f"Failed to poll research status after {consecutive_failures} attempts") from e
                await asyncio.sleep(poll_interval)

    async def stream(self, research_id: str) -> AsyncIterator[ResearchEvent]:
        response = await self.http_client.async_request(f"/research/{research_id}/stream", method="GET")
        async for line in response.aiter_lines():
            if not line or not line.strip():
                continue
            try:
                import json
                decoded_line = line.encode('utf-8').decode('utf-8') if isinstance(line, str) else line.decode('utf-8')
                decoded_line = decoded_line.removeprefix("data: ").strip()
                if not decoded_line or decoded_line == "[DONE]":
                    continue
                event_data = json.loads(decoded_line)
                event = ResearchEvent.model_validate(event_data)
                yield event
            except Exception:
                continue
