from ..types import WebsetImport, CreateWebsetImportParameters

class ImportsClient(WebsetsBaseClient):
    def __init__(self, http_client):
        super().__init__(http_client)

    def create(self, webset_id: str, rows: List[Dict[str, Any]], has_header: bool = True) -> WebsetImport:
        csv_content = self._rows_to_csv(rows, has_header=has_header)
        calculated_count = max(0, len(rows) - (1 if has_header else 0))
        params = CreateWebsetImportParameters(
            import_type="csv",
            count=calculated_count
        )
        prepared = self._prepare_data(params)
        response = self.http_client.request(f"/websets/{webset_id}/imports", prepared["data"], method="POST")
        webset_import = WebsetImport.model_validate(response)
        if webset_import.upload_url:
            upload_response = requests.put(webset_import.upload_url, data=csv_content, headers={"Content-Type": "text/csv"})
            if upload_response.status_code >= 400:
                raise Exception(f"Failed to upload CSV: {upload_response.status_code}")
        return webset_import

    def get(self, webset_id: str, import_id: str) -> WebsetImport:
        response = self.http_client.request(f"/websets/{webset_id}/imports/{import_id}", method="GET")
        return WebsetImport.model_validate(response)

    def _rows_to_csv(self, rows: List[Dict[str, Any]], has_header: bool = True) -> str:
        if not rows:
            return ""
        output = io.StringIO()
        fieldnames = list(rows[0].keys())
        writer = csv.DictWriter(output, fieldnames=fieldnames)
        if has_header:
            writer.writeheader()
        writer.writerows(rows)
        return output.getvalue()

