        webset_import = WebsetImport.model_validate(response)
        if webset_import.upload_url:
            upload_response = await self._async_http_client.put(webset_import.upload_url, content=csv_content, headers={"Content-Type": "text/csv"})
            if upload_response.status_code >= 400:
                raise Exception(f"Failed to upload CSV: {upload_response.status_code}")
