def snake_to_camel(snake_str: str) -> str:
    components = [c for c in snake_str.split("_") if c]
    if not components:
        return ""
    return components[0].lower() + ''.join(x.title() for x in components[1:])

def camel_to_snake(camel_str: str) -> str:
    snake_str = re.sub(r'(.)([A-Z][a-z]+)', r'\1_\2', camel_str)
    return re.sub(r'([a-z0-9])([A-Z])', r'\1_\2', snake_str).lower()

def to_camel_case(data: dict, skip_keys: list = None) -> dict:
    if skip_keys is None:
        skip_keys = []
    if not isinstance(data, dict):
        return data
    result = {}
    for key, value in data.items():
        if key in skip_keys:
            new_key = key
        elif key == "schema_":
            new_key = "$schema"
        elif key == "not_":
            new_key = "not"
        else:
            new_key = snake_to_camel(key)
        if isinstance(value, dict):
            result[new_key] = to_camel_case(value, skip_keys)
        elif isinstance(value, list):
            result[new_key] = [to_camel_case(v, skip_keys) if isinstance(v, dict) else v for v in value]
        else:
            result[new_key] = value
    return result

def to_snake_case(data: dict) -> dict:
    if not isinstance(data, dict):
        return data
    result = {}
    for key, value in data.items():
        new_key = camel_to_snake(key)
        if isinstance(value, dict):
            result[new_key] = to_snake_case(value)
        elif isinstance(value, list):
            result[new_key] = [to_snake_case(v) if isinstance(v, dict) else v for v in value]
        else:
