@dataclass
class AnswerResult:
    url: str
    title: Optional[str] = None
    text: Optional[str] = None

@dataclass
class StreamChunk:
    content: Optional[str] = None
    citations: Optional[List[AnswerResult]] = None

    def has_data(self) -> bool:
        return bool(self.content) or bool(self.citations)

    def __str__(self) -> str:
        output = ""
        if self.content:
            output += self.content
        return output

@dataclass
class AnswerResponse:
    answer: Union[str, dict]
    citations: List[AnswerResult]

    def __str__(self):
        output = f"Answer: {self.answer}\n\nCitations:"
        for citation in self.citations:
            output += f"\n  - {citation.title}: {citation.url}"
        return output

class StreamAnswerResponse:
    def __init__(self, raw_response: requests.Response):
        self.raw_response = raw_response
        self._ensure_ok_status()

    def _ensure_ok_status(self):
        if self.raw_response.status_code >= 400:
            try:
                error_data = self.raw_response.json()
                raise Exception(f"API Error: {error_data}")
            except:
                raise Exception(f"HTTP Error {self.raw_response.status_code}")

    def __iter__(self) -> Iterator[StreamChunk]:
        for line in self.raw_response.iter_lines():
            if not line:
                continue
            try:
                decoded_line = line.decode("utf-8").removeprefix("data: ").strip()
                if not decoded_line or decoded_line == "[DONE]":
                    continue
                chunk = json.loads(decoded_line)
                content = None
                citations = None
                if "choices" in chunk and len(chunk["choices"]) > 0:
                    delta = chunk["choices"][0].get("delta", {})
                    content = delta.get("content")
                    if "citations" in delta:
                        citations = []
                        for c in delta["citations"]:
                            snake_c = to_snake_case(c)
                            citations.append(AnswerResult(**snake_c))
                stream_chunk = StreamChunk(content=content, citations=citations)
                if stream_chunk.has_data():
                    yield stream_chunk
            except Exception:
                continue

    def close(self) -> None:
        self.raw_response.close()

class AsyncStreamAnswerResponse:
    def __init__(self, raw_response: httpx.Response):
        self.raw_response = raw_response

    def __aiter__(self):
        return self.generator()

    async def generator(self):
        async for line in self.raw_response.aiter_lines():
            if not line:
                continue
            try:
                decoded_line = line.encode('utf-8').decode('utf-8') if isinstance(line, str) else line.decode('utf-8')
                decoded_line = decoded_line.removeprefix("data: ").strip()
