T = TypeVar("T")

@dataclass
class ContentStatus:
    status: str
    source: str

@dataclass
class SearchResponse(Generic[T]):
    results: List[T]
    autoprompt_string: Optional[str] = None
    resolved_search_type: Optional[str] = None
    auto_date: Optional[str] = None
    context: Optional[str] = None
    statuses: Optional[List[ContentStatus]] = None
    cost_dollars: Optional[CostDollars] = None

    def __str__(self):
        output = "\n\n".join(str(result) for result in self.results)
        return output

def nest_fields(original_dict: Dict, fields_to_nest: List[str], new_key: str) -> Dict:
    nested_dict = {}
    for field in fields_to_nest:
        if field in original_dict:
            nested_dict[field] = original_dict.pop(field)
    if nested_dict:
        original_dict[new_key] = nested_dict
    return original_dict

def _get_package_version() -> str:
    try:
        import tomllib
        current_dir = os.path.dirname(os.path.abspath(__file__))
        project_root = os.path.dirname(current_dir)
        pyproject_path = os.path.join(project_root, "pyproject.toml")
        if not os.path.exists(pyproject_path):
            return "unknown"
        with open(pyproject_path, 'rb') as f:
            data = tomllib.load(f)
            return data.get("project", {}).get("version", "unknown")
    except Exception:
        return "unknown"

